fn min_inspectors(n: i8, d: i8) -> i8 {
    // n: number of items (1..=20), d: radius (1..=20)
    // Each inspector covers a block of length (2*d + 1), so answer is ceil(n / (2*d + 1)).
    let n_i = n as i32;
    let d_i = d as i32;

    let cover = 2 * d_i + 1;              // >= 3
    let result = (n_i + cover - 1) / cover; // ceil division

    result as i8
}